mapper.insert:
/*
	SQL ID : DscsFdbkDAO.insertFdbk
	설명 : 피드백 등록
*/
INSERT INTO TB_LMS_DSCS_FDBK (
	DSCS_FDBK_ID
	, DSCS_ID
	, USER_ID
	, UP_DSCS_FDBK_ID
	, TEAM_ID
	, DSCS_FDBK_CTS
	, DELYN
	, RGTR_ID
	, REG_DTTM
	, MDFR_ID
	, MOD_DTTM
)
VALUES (
	#{dscsFdbkId}
	, #{dscsId}
	, #{stdId}
	, #{upDscsFdbkId}
	, #{teamId}
	, #{dscsFdbkCts}
	, 'N'
	, #{rgtrId}
	, FN_DTTM()
	, #{mdfrId}
	, FN_DTTM()
)

mapper.update:
/*
	SQL ID : DscsFdbkDAO.updateFdbk
	설명 : 피드백 수정 및 삭제 여부 변경
*/
UPDATE TB_LMS_DSCS_FDBK
   SET MDFR_ID = #{mdfrId}
	   , MOD_DTTM = FN_DTTM()

	   , UP_DSCS_FDBK_ID = #{upDscsFdbkId}


	   , TEAM_ID = #{teamId}


	   , DSCS_FDBK_CTS = #{dscsFdbkCts}


	   , DELYN = #{delYn}

 WHERE DSCS_FDBK_ID = #{dscsFdbkId}

   AND DSCS_ID = #{dscsId}


   AND USER_ID = #{stdId}

mapper.select:
/*
	SQL ID : DscsFdbkDAO.cntFdbk
	설명 : 피드백 개수 조회
*/
SELECT
	COUNT(*) AS cntFdbk
FROM TB_LMS_DSCS_FDBK
WHERE DSCS_ID = #{dscsId}
	AND USER_ID = #{stdId}
	AND DELYN = 'N'
